  \rowcolor{primary!15}
  \bfseries\color{primary} Rank & \bfseries\color{primary} University & \bfseries\color{primary} Country & \bfseries\color{primary} Score \\
  \color{primary}\textbf{1} & \textbf{Massachusetts Institute of Technology (MIT)} & US & \textbf{100} \\
  \rowcolor{darkbg!50!white}
  2 & Imperial College London & UK & 98.5 \\
  3 & University of Oxford & UK & 97.9 \\
  \rowcolor{darkbg!50!white}
  4 & Harvard University & US & 97.6 \\
  5 & University of Cambridge & UK & 97.0 \\
  \rowcolor{darkbg!50!white}
  6 & Stanford University & US & 96.8 \\
  7 & ETH Zurich & Switzerland & 95.3 \\
  \rowcolor{darkbg!50!white}
  8 & National University of Singapore (NUS) & Singapore & 94.7 \\
  9 & UCL (University College London) & UK & 94.2 \\
  \rowcolor{darkbg!50!white}
  10 & California Institute of Technology & US & 93.8 \\
  \end{tabular}
  \end{center}
  \vspace{24pt}

