]{name=trends, column=2, span=2, between=row14 and bottom}{
  \fontsize{38}{50}\selectfont
  \begin{itemize}[itemsep=24pt]
    \item \textbf{Asian universities continue to rise:} Several Chinese and South Korean institutions have climbed significantly, reflecting sustained investment in research infrastructure and international collaboration.
    \item \textbf{UK strength persists:} With 4 universities in the global top 10 and 17 in the top 100, the United Kingdom remains the second most represented country after the United States.
    \item \textbf{Sustainability \& employability focus:} QS has expanded supplementary rankings to include sustainability metrics and employer outcomes, reflecting evolving priorities in higher education.
    \item \textbf{Most comprehensive coverage yet:} Evaluates over 1,500 institutions, spanning 105 countries, more than any previous year.
  \end{itemize}
}

\end{tcbposter}
